SELECT REPORT_DATE AS `报告期`, SEC_NAME AS `股票名称`, COMB_SYMBOL AS `股票代码`, ROUND(MARKET_VALUE/100000000, 1) AS `持股市值(亿)`, ROUND(RATIO_IN_NV*100, 2) AS `持股占基金净资产比例(%)`, SHARES_HOLDING AS `持股数量(股)` FROM FUND_PORTFOLIO_DETAIL WHERE FUND_NAME LIKE '%大成高新技术产业股票A%' AND REPORT_DATE = '2026-06-30' AND FUND_HOLDING_SOURCE_ID = 1 AND MARKET_VALUE IS NOT NULL AND HISVALID = 1 ORDER BY MARKET_VALUE DESC LIMIT 1;
